#include <bits/stdc++.h>
using namespace std;

static string in;
static size_t p = 0;
static void readAll() {
    char b[1 << 16];
    size_t k;
    while ((k = fread(b, 1, sizeof b, stdin)) > 0) in.append(b, k);
}
static bool skipSpace() {
    while (p < in.size() && (unsigned char)in[p] <= ' ') p++;
    return p < in.size();
}
static string token() {
    skipSpace();
    size_t s = p;
    while (p < in.size() && (unsigned char)in[p] > ' ') p++;
    return in.substr(s, p - s);
}
static long long num() {
    skipSpace();
    bool neg = false;
    if (p < in.size() && (in[p] == '-' || in[p] == '+')) neg = in[p++] == '-';
    long long v = 0;
    while (p < in.size() && in[p] >= '0' && in[p] <= '9') v = v * 10 + (in[p++] - '0');
    return neg ? -v : v;
}

int main() {
    readAll();
    num();  // n: every following number is a capacity
    vector<long long> a;
    while (skipSpace()) a.push_back(num());
    int n = a.size();
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
    // Stable [l, r]: a[l] == a[r] and P[r] - P[l + 1] == a[l], i.e. key (a[l], P[l+1] + a[l]) == (a[r], P[r]).
    map<pair<long long, long long>, long long> counts;
    long long answer = 0;
    for (int r = 0; r < n; r++) {
        int l = r - 2;  // only left ends at distance >= 2 keep the length >= 3
        if (l >= 0) counts[{a[l], prefix[l + 1] + a[l]}]++;
        auto it = counts.find({a[r], prefix[r]});
        if (it != counts.end()) answer += it->second;
    }
    printf("%lld\n", answer);
}

import java.util.HashMap;

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    record Key(long value, long sum) {}

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        num();  // n: every following number is a capacity
        long[] buf = new long[16];
        int n = 0;
        while (skipSpace()) {
            if (n == buf.length) buf = java.util.Arrays.copyOf(buf, 2 * n);
            buf[n++] = num();
        }
        long[] a = buf;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
        // Stable [l, r]: a[l] == a[r] and P[r] - P[l + 1] == a[l], i.e. key (a[l], P[l+1] + a[l]) == (a[r], P[r]).
        HashMap<Key, Long> counts = new HashMap<>();
        long answer = 0;
        for (int r = 0; r < n; r++) {
            int l = r - 2;  // only left ends at distance >= 2 keep the length >= 3
            if (l >= 0) counts.merge(new Key(a[l], prefix[l + 1] + a[l]), 1L, Long::sum);
            answer += counts.getOrDefault(new Key(a[r], prefix[r]), 0L);
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	num() // n: every following number is a capacity
	a := []int64{}
	for skipSpace() {
		a = append(a, num())
	}
	n := len(a)
	prefix := make([]int64, n+1)
	for i, v := range a {
		prefix[i+1] = prefix[i] + v
	}
	// Stable [l, r]: a[l] == a[r] and P[r] - P[l + 1] == a[l], i.e. key (a[l], P[l+1] + a[l]) == (a[r], P[r]).
	type key struct{ value, sum int64 }
	counts := map[key]int64{}
	var answer int64
	for r := 0; r < n; r++ {
		if l := r - 2; l >= 0 { // only left ends at distance >= 2 keep the length >= 3
			counts[key{a[l], prefix[l+1] + a[l]}]++
		}
		answer += counts[key{a[r], prefix[r]}]
	}
	fmt.Println(answer)
}
